mapper.select:
SELECT id, tenant_id, user_id, question, rating, feedback_comment, review_status, resolution_note
FROM answer_record
WHERE tenant_id = #{tenantId} AND id = #{id}

SELECT id, answer_text, refused, refusal_reason, top_relevance
FROM answer_record
WHERE tenant_id = #{tenantId}
  AND id IN #{id}

SELECT c.answer_id, c.citation_index, c.chunk_id, c.document_id, c.document_name, c.heading_path
FROM answer_citation c JOIN answer_record r ON r.id = c.answer_id
WHERE r.tenant_id = #{tenantId}
  AND c.answer_id IN #{id}
ORDER BY c.answer_id, c.citation_index

mapper.sql:
WHERE r.tenant_id = #{tenantId}
AND r.rating = 'DOWN'
AND r.refused
AND r.review_status = #{status}
AND r.created_at >= #{since}
AND r.question ILIKE '%' || #{keyword} || '%'
